import { Database } from 'bun:sqlite';
import { readdir } from 'fs/promises';

interface MigrationResult {
  applied: string[];
  failed: string[];
}

export async function runMigrations(migrationsDir: string): Promise<MigrationResult> {
  const files = await readdir(migrationsDir);
  const sqlFiles = files.filter(f => f.endsWith('.sql')).sort();

  const applied: string[] = [];
  const failed: string[] = [];

  for (const file of sqlFiles) {
    const db = new Database('app.db');

    try {
      const sql = await Bun.file(`${migrationsDir}/${file}`).text();
      db.run(sql);
      applied.push(file);
    } catch (error) {
      failed.push(file);
      // Continue with next migration
    }
  }

  return { applied, failed };
}

export async function exportData(tables: string[]): Promise<Record<string, unknown[]>> {
  const result: Record<string, unknown[]> = {};

  for (const table of tables) {
    const db = new Database('app.db');
    result[table] = db.query(`SELECT * FROM ${table}`).all();
  }

  return result;
}

export function watchDatabase(callback: (change: string) => void): void {
  setInterval(() => {
    const db = new Database('app.db');
    const changes = db.query('SELECT * FROM change_log WHERE processed = 0').all();
    for (const change of changes) {
      callback(JSON.stringify(change));
    }
    db.run('UPDATE change_log SET processed = 1 WHERE processed = 0');
  }, 1000);
}
